import { TransferQueue } from './TransferQueue'

@Entry
@Component
export struct TransferPanel {
  @State destination: string = ''
  private queue: TransferQueue = new TransferQueue()

  submitTransfer(): void {
    if (this.destination.trim().length === 0) {
      promptAction.showToast({ message: 'Transfer destination is required' })
      return
    }
    this.queue.enqueue(this.destination)
  }

  build() { Text(this.destination) }
}

